// Presupuesto con alertas. Gasto diario INVENTADO de un entorno de pruebas, en USD.
const presupuesto = 300;                       // USD por mes (inventado)
const dias = 30;
const gasto = Array.from({ length: dias }, (_, i) => (i < 10 ? 6 : 12) + (i >= 14 && i <= 17 ? 28 : 0));
// días 15 a 18: alguien dejó un bucle encendido (+28 por día)
const umbrales = [0.5, 0.8, 1.0];
const demora = 1;                              // el proveedor informa el costo con 1 día de atraso (supuesto)
let acumulado = 0;
const avisadoReal = new Set(), avisadoPrev = new Set();
for (let d = 1; d <= dias; d++) {
  acumulado += gasto[d - 1];
  const visible = gasto.slice(0, Math.max(0, d - demora)).reduce((a, b) => a + b, 0);
  const ritmo = d > demora ? visible / (d - demora) : 0;         // promedio diario visible
  const previsto = visible + ritmo * (dias - (d - demora));      // proyección lineal al fin de mes
  for (const u of umbrales) {
    if (!avisadoReal.has(u) && visible >= u * presupuesto) { avisadoReal.add(u); console.log(`día ${d}: alerta REAL al ${u * 100} % (gasto visible USD ${visible}; gasto verdadero USD ${acumulado})`); }
    if (!avisadoPrev.has(u) && previsto >= u * presupuesto && u === 1.0) { avisadoPrev.add(u); console.log(`día ${d}: alerta PREVISTA al ${u * 100} % (el ritmo llevaría el mes a USD ${previsto.toFixed(0)})`); }
  }
}
console.log(`Gasto final del mes: USD ${acumulado} (presupuesto USD ${presupuesto})`);

// Reserva vs a demanda. Precios de LISTA: instancia t3.small Linux, región sa-east-1 (São Paulo),
// lista oficial de AWS publicada el 14-11-2026. La flota y las horas de uso son INVENTADAS.
const P = { demanda: 0.0336, r1: 0.0193, r3: 0.0145, anual1Todo: 158, trienal3Todo: 332 }; // USD por hora / pago único
const H_ANIO = 8760;
const quedaCon = (h) => h * H_ANIO;
console.log("Un solo equipo encendido todo el año (8.760 h):");
console.log(`  a demanda ............ USD ${(P.demanda * H_ANIO).toFixed(2)}`);
console.log(`  reserva 1 año, sin pago inicial .. USD ${(P.r1 * H_ANIO).toFixed(2)}  (ahorro ${(100 * (1 - P.r1 / P.demanda)).toFixed(1)} %)`);
console.log(`  reserva 3 años, sin pago inicial . USD ${(P.r3 * H_ANIO).toFixed(2)} por año  (ahorro ${(100 * (1 - P.r3 / P.demanda)).toFixed(1)} %)`);
console.log(`  reserva 1 año, todo adelantado ... USD ${P.anual1Todo.toFixed(2)}  (ahorro ${(100 * (1 - P.anual1Todo / (P.demanda * H_ANIO))).toFixed(1)} %)`);
console.log(`Punto de equilibrio (1 año, sin pago inicial): ${(100 * P.r1 / P.demanda).toFixed(1)} % de las horas del año`);
// Flota inventada: 6 equipos 24/7 y 4 equipos de 10 h por día hábil (220 h por mes).
const fijos = 6, variables = 4, horasVariables = 220 * 12;
const aDemanda = fijos * P.demanda * H_ANIO + variables * P.demanda * horasVariables;
const reservaTodo = (fijos + variables) * P.r1 * H_ANIO;                      // error: reservar también los de uso parcial
const reservaSolo = fijos * P.r1 * H_ANIO + variables * P.demanda * horasVariables; // reservar solo lo constante
console.log("Flota inventada: 6 equipos 24/7 + 4 equipos de 220 h por mes (por año):");
console.log(`  todo a demanda .................... USD ${aDemanda.toFixed(2)}`);
console.log(`  reservar los 10 (1 año, sin inicial) USD ${reservaTodo.toFixed(2)}`);
console.log(`  reservar solo los 6 constantes .... USD ${reservaSolo.toFixed(2)}`);
